{"summary": "Create gzipped text source for Flink to read local .gz CSV lines", "command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/GzipTextSource.java", "file_text": "package clusterdata.utils;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

public class GzipTextSource implements SourceFunction<String> {

    private final String path;
    private volatile boolean running = true;

    public GzipTextSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<String> ctx) throws Exception {
        try (InputStream fileIn = new FileInputStream(path);
             InputStream in = path.endsWith(".gz") ? new GZIPInputStream(fileIn) : fileIn;
             BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = reader.readLine()) != null) {
                if (!line.isEmpty()) {
                    ctx.collect(line);
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
"}

{"summary": "Create local file sink writing one line per record", "command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/LocalFileSink.java", "file_text": "package clusterdata.utils;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;

public class LocalFileSink extends RichSinkFunction<String> {

    private final String outputPath;
    private transient BufferedWriter writer;

    public LocalFileSink(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        File outFile = new File(outputPath);
        File parent = outFile.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }
        writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(outFile, false), StandardCharsets.UTF_8));
    }

    @Override
    public synchronized void invoke(String value, Context context) throws Exception {
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }
}
"}

