                .filter(e -> e.eventType == TaskEvent.EVENT_SUBMIT)
                .connect(jobEventsStream.filter(e -> e.eventType == JobEvent.EVENT_FINISH))
                .keyBy(t -> t.jobId, j -> j.jobId)
